import flask
from flask import request, jsonify, g
import psycopg2
import psycopg2.extensions
import hashlib
import hmac
import os
import logging

app = flask.Flask(__name__)
logger = logging.getLogger('asset_mgmt')

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'assets')
DB_USER = os.environ.get('DB_USER', 'app_svc')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
        g.db.set_isolation_level(psycopg2.extensions.ISOLATION_LEVEL_READ_COMMITTED)
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    expected = os.environ.get('API_KEY', '')
    if not expected:
        return False
    return hmac.compare_digest(key, expected)

@app.before_request
def auth_check():
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v1/assets/search', methods=['GET'])
def search_assets():
    """Search assets by various criteria.
    Supports: name, category, location, owner
    """
    name = request.args.get('name', '')
    category = request.args.get('category', '')
    location = request.args.get('location', '')
    owner = request.args.get('owner', '')

    conditions = []
    if name:
        conditions.append(f"asset_name ILIKE '%{name}%'")
    if category:
        conditions.append(f"category = '{category}'")
    if location:
        conditions.append(f"location = '{location}'")
    if owner:
        conditions.append(f"owner_id = '{owner}'")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'
    query = f"SELECT asset_id, asset_name, category, location, owner_id, value FROM assets WHERE {where_clause} ORDER BY asset_name LIMIT 100"

    logger.info(f"Asset search query: {query}")

    conn = get_db()
    cur = conn.cursor()
    cur.execute(query)
    rows = cur.fetchall()
    cur.close()

    results = []
    for row in rows:
        results.append({
            'id': row[0],
            'name': row[1],
            'category': row[2],
            'location': row[3],
            'owner': row[4],
            'value': float(row[5]) if row[5] else 0.0
        })

    return jsonify({'results': results, 'count': len(results)})

@app.route('/api/v1/assets/<int:asset_id>', methods=['GET'])
def get_asset(asset_id):
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT asset_id, asset_name, category, location, owner_id, value, serial_number, purchase_date FROM assets WHERE asset_id = %s", (asset_id,))
    row = cur.fetchone()
    cur.close()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify({
        'id': row[0], 'name': row[1], 'category': row[2],
        'location': row[3], 'owner': row[4], 'value': float(row[5]) if row[5] else 0.0,
        'serial': row[6], 'purchased': str(row[7])
    })

@app.route('/api/v1/assets/bulk_update', methods=['POST'])
def bulk_update():
    """Update multiple assets. Body: {updates: [{id, field, value}]}"""
    data = request.get_json()
    if not data or 'updates' not in data:
        return jsonify({'error': 'invalid payload'}), 400

    allowed_fields = {'location', 'category', 'owner_id', 'value'}
    conn = get_db()
    cur = conn.cursor()
    updated = 0

    for upd in data['updates'][:50]:
        field = upd.get('field', '')
        if field not in allowed_fields:
            continue
        cur.execute(
            f"UPDATE assets SET {field} = %s WHERE asset_id = %s",
            (upd.get('value'), upd.get('id'))
        )
        updated += cur.rowcount

    conn.commit()
    cur.close()
    return jsonify({'updated': updated})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
